code='''def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    # A vertical 5-bar is completed by repeating the color block attached
    # to its lower end into the empty area on its right.
    for c in range(w):
        r = 0
        while r < h:
            if g[r][c] != 5:
                r += 1
                continue
            top = r
            while r + 1 < h and g[r + 1][c] == 5:
                r += 1
            bottom = r
            if c + 1 < w and bottom > top and any(g[bottom][x] != 0 for x in range(c + 1, w)):
                right = c + 1
                while right < w and g[bottom][right] != 0:
                    right += 1
                motif = []
                y = bottom
                while y >= top and g[y][c + 1] != 0:
                    motif.append(g[y][c + 1:right])
                    y -= 1
                if motif:
                    for y in range(top, bottom + 1):
                        pattern = motif[(bottom - y) % len(motif)]
                        for dx, value in enumerate(pattern, c + 1):
                            if g[y][dx] == 0:
                                g[y][dx] = value
            r += 1

    # The transposed case: a horizontal 5-bar with a vertical color block
    # attached below its left end is extended to the right.
    for r in range(h):
        c = 0
        while c < w:
            if g[r][c] != 5:
                c += 1
                continue
            left = c
            while c + 1 < w and g[r][c + 1] == 5:
                c += 1
            right = c
            if r + 1 < h and right > left and g[r + 1][left] != 0:
                bottom = r + 1
                while bottom < h and g[bottom][left] != 0:
                    bottom += 1
                motif = [g[y][left] for y in range(r + 1, bottom)]
                for x in range(left, right + 1):
                    for dy, value in enumerate(motif, r + 1):
                        if g[dy][x] == 0:
                            g[dy][x] = value
            c += 1
    return g
'''
